import{_ as s,C as r,o as i,c as t,a6 as n,E as d,j as a,a as l}from"./chunks/framework.CKIbuWFA.js";const f=JSON.parse('{"title":"Revise alterações por área","description":"","frontmatter":{"title":"Revise alterações por área","docId":"user.cloud.changes","translationKey":"user.cloud.changes","locale":"pt","audience":"user","featureStatus":"available","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"f875a22e66dd822d7ea1344188d8b7b087a23a777e072240a4a3c7c57969f995","translationRevision":"4227e2b6755c6c7032fc887c3b0772bd2d33364d120b710d415f8234e2444fb8","order":20},"headers":[],"relativePath":"pt/user/cloud/changes.md","filePath":"pt/user/cloud/changes.md","lastUpdated":1794611623000}'),c={name:"pt/user/cloud/changes.md"};function p(u,e,m,v,h,g){const o=r("DemoFrame");return i(),t("div",null,[e[0]||(e[0]=n('<h1 id="review-changes-by-area" tabindex="-1">Revise alterações por área <a class="header-anchor" href="#review-changes-by-area" aria-label="Permalink to &quot;Revise alterações por área {#review-changes-by-area}&quot;">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">Objetivo e pré-requisitos <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to &quot;Objetivo e pré-requisitos {#goal-and-prerequisites}&quot;">​</a></h2><p>Entenda o que um painel <strong>Changes</strong> compara antes de redefinir, enviar ou adotar dados. Você precisa de conteúdo local salvo. Operações do Cloud também precisam de um host compatível, do modo de sincronização relevante e de uma <a href="./account.html">conta autenticada</a>. Painéis com o mesmo nome não realizam todos o mesmo transporte.</p><h2 id="review-events-and-actions-locally" tabindex="-1">Revise Events e Actions localmente <a class="header-anchor" href="#review-events-and-actions-locally" aria-label="Permalink to &quot;Revise Events e Actions localmente {#review-events-and-actions-locally}&quot;">​</a></h2><ol><li>Abra <strong>Automations</strong>, selecione Events ou Actions e abra <strong>Changes</strong>.</li><li>Leia o aviso: essa área compara as definições atuais com uma referência mantida neste dispositivo. A primeira visita carregada inicializa essa referência, portanto pode legitimamente não mostrar alterações.</li><li>Selecione um registro adicionado, modificado ou excluído e inspecione os valores anteriores e posteriores.</li><li>Escolha <strong>Mark as reviewed</strong> somente quando quiser que a seção atual se torne a nova referência local. Isso não envia definições nem aprova execução delegada.</li><li>Use <strong>Reset</strong> apenas quando pretender restaurar a referência. Para um registro recém-adicionado, a redefinição o remove; para um registro modificado/excluído, ela restaura a definição mantida. Salve uma exportação antes, se necessário.</li></ol><p>O adaptador de Events/Actions não tem coleção do Cloud para definições individuais nesta versão. Uma comparação sem alterações não é um backup no Cloud nem prova de que outro computador recebeu suas edições.</p><h2 id="review-variables-and-plugins-explicitly" tabindex="-1">Revise Variables e Plugins explicitamente <a class="header-anchor" href="#review-variables-and-plugins-explicitly" aria-label="Permalink to &quot;Revise Variables e Plugins explicitamente {#review-variables-and-plugins-explicitly}&quot;">​</a></h2><p>Variables tem seu próprio compartilhamento nativo revisado: salve localmente, busque candidatas, inspecione a comparação e explicitamente envie, aplique/adote ou retire. Valores secretos ou bloqueados continuam mascarados e não podem ser enviados por esse caminho. Salvar localmente nunca envia. Consulte <a href="./../automations/variables.html">Variables</a>.</p><p>Changes de Plugins usa seu workspace de sincronização compatível para seleções de plugins e configurações preparadas. A publicação ocorre por seção, em vez de um envio separado para cada linha. As configurações mostram nomes das chaves alteradas sem expor valores; conflitos permitem escolher a versão local ou do Cloud, não mesclar campos arbitrariamente. Leia a ação da seção e o modo de sincronização selecionado antes de publicar.</p><p>Overlays do Cloud usam o fluxo de criação/revisão da <a href="./../overlays/">biblioteca/editor</a>. Um adaptador compartilhado Changes de overlays não está disponível nesta versão base.</p><h2 id="expected-result-status-and-recovery" tabindex="-1">Resultado esperado, status e recuperação <a class="header-anchor" href="#expected-result-status-and-recovery" aria-label="Permalink to &quot;Resultado esperado, status e recuperação {#expected-result-status-and-recovery}&quot;">​</a></h2><p>A comparação local de automações e o compartilhamento nativo condicionado às capacidades estão disponíveis nas respectivas áreas. Operações com efeitos remotos dependem do serviço; isso não implica aceitação em produção. Se uma revisão ficar desatualizada, atualize e compare novamente. Se o resultado não estiver confirmado, inspecione as informações de status/diário antes de criar outra operação. Nunca trate um tempo limite como prova de que nada mudou.</p>',12)),d(o,{scenario:"cloud",locale:"pt",tour:"changes",title:"Demonstração: Cloud"}),e[1]||(e[1]=a("h2",{id:"operational-details",tabindex:"-1"},[l("Detalhes de operação "),a("a",{class:"header-anchor",href:"#operational-details","aria-label":'Permalink to "Detalhes de operação {#operational-details}"'},"​")],-1)),e[2]||(e[2]=a("p",null,"Antes de preparar/migrar v1 → v2, faça backup e coordene versões compatíveis em todos os dispositivos. No setup prepare, confira compatibilidade e visualize; revise contagens de seleção, pendências, conflitos e itens só-v1, sem presumir sincronização. Exigir cabeçalho de época é irreversível para escritas v2 de toda a conta e pode rejeitar dispositivos antigos. Timeout da barreira é ambíguo; repeti-la avança novamente. Atualize estado de época/migração e prévia antes de agir. Ler época não comprova escritas anteriores concluídas.",-1)),e[3]||(e[3]=a("p",null,"A recuperação depende do modo: Changes de Events/Actions compara referências locais, sem escrita Cloud. Para Variables/Plugins revisados, atualize comparações expiradas e confira revisão, conta e inventário. Se faltarem plugins, use revisão/reparo de inventário do setup e outra prévia. Para intenção incerta, preserve ID/evidência e consulte histórico/estado; recuperação técnica exige nova revisão das entradas congeladas e revisão Cloud. Retomar essa intenção não envia escrita remota por si só. Pare sem criar mutação substituta se não puder reconciliar.",-1))])}const x=s(c,[["render",p]]);export{f as __pageData,x as default};
